#!/usr/bin/env python3
"""Make the active local-model authority Qwen-3.8-only and update stale tests.

Legacy tiny variants remain private source fixtures temporarily, but they are no
longer returned by `all`, `defaultVariant`, `safestVariant`, or `variant(for:)`.
The test edits only replace assertions that explicitly described the deleted
small-model fallback product; protocol/security tests keep their full coverage.
"""
from pathlib import Path

runtime_path = Path("AgentPad/Services/LocalModelRuntime.swift")
runtime = runtime_path.read_text(encoding="utf-8")

legacy_decl = "    static let all: [LocalModelVariant] = [\n"
legacy_private = "    private static let legacyCatalog: [LocalModelVariant] = [\n"
if legacy_decl in runtime:
    if runtime.count(legacy_decl) != 1:
        raise SystemExit("ambiguous active catalog declaration")
    runtime = runtime.replace(legacy_decl, legacy_private, 1)
elif legacy_private not in runtime:
    raise SystemExit("active catalog declaration drifted")

insert_marker = "    ]\n\n    static var exactQwen38Variant: LocalModelVariant? {\n"
inserted = "    ]\n\n    /// The active runtime catalog is the exact Qwen 3.8 27B target only.\n    /// Legacy variants above are private historical fixtures and can never be\n    /// selected as a production fallback.\n    static var all: [LocalModelVariant] {\n        presentationOrder\n    }\n\n    static var exactQwen38Variant: LocalModelVariant? {\n"
if insert_marker in runtime:
    if runtime.count(insert_marker) != 1:
        raise SystemExit("ambiguous Qwen 3.8 catalog insertion marker")
    runtime = runtime.replace(insert_marker, inserted, 1)
elif inserted not in runtime:
    raise SystemExit("Qwen 3.8 catalog insertion marker drifted")

old_safest = '''    static func safestVariant(forPhysicalMemory physicalMemory: UInt64 = ProcessInfo.processInfo.physicalMemory) -> LocalModelVariant {\n        all.first { $0.isIPhone12SafeDefault && physicalMemory >= $0.minimumPhysicalMemoryBytes }\n            ?? all.first { $0.deviceFit != .extreme && physicalMemory >= $0.minimumPhysicalMemoryBytes }\n            ?? all.first { $0.deviceFit != .extreme }\n            ?? all.last!\n    }\n'''
new_safest = '''    static func safestVariant(forPhysicalMemory physicalMemory: UInt64 = ProcessInfo.processInfo.physicalMemory) -> LocalModelVariant {\n        // Qwen-3.8-only build: memory pressure may change the execution profile,\n        // never the model identity. No smaller substitute is permitted.\n        defaultVariant\n    }\n'''
if old_safest in runtime:
    runtime = runtime.replace(old_safest, new_safest, 1)
elif new_safest not in runtime:
    raise SystemExit("safestVariant contract drifted")

runtime_path.write_text(runtime, encoding="utf-8")

transport_test_path = Path("AgentPadTests/AgentLocalModelProviderTransportTests.swift")
transport_tests = transport_test_path.read_text(encoding="utf-8")
old_static_test = '''    func testStaticCatalogDoesNotSelfAwardDeviceQualification() {\n        let defaultVariant = LocalModelCatalog.defaultVariant\n        XCTAssertTrue(defaultVariant.isIPhone12SafeDefault)\n        XCTAssertEqual(defaultVariant.deviceFit.title, "Qualification pending")\n        XCTAssertEqual(defaultVariant.deviceFit.symbol, "iphone")\n        XCTAssertTrue(\n            defaultVariant.benchmarkSummary.localizedCaseInsensitiveContains(\n                "exact-device qualification pending"\n            )\n        )\n        XCTAssertTrue(\n            defaultVariant.details.localizedCaseInsensitiveContains(\n                "exact-device qualification remains pending"\n            )\n        )\n\n        let forbiddenStaticClaims = [\n            "Device proven",\n            "physical-device canary proven",\n            "The proven iPhone 12 default",\n        ]\n        for variant in LocalModelCatalog.all {\n            let staticPresentation = [\n                variant.deviceFit.title,\n                variant.benchmarkSummary,\n                variant.details,\n            ].joined(separator: " ")\n            for claim in forbiddenStaticClaims {\n                XCTAssertFalse(\n                    staticPresentation.localizedCaseInsensitiveContains(claim),\n                    "Static catalog metadata must not self-award device qualification: \\(claim)"\n                )\n            }\n        }\n    }\n'''
new_static_test = '''    func testStaticCatalogDoesNotSelfAwardDeviceQualification() {\n        let target = LocalModelCatalog.defaultVariant\n        XCTAssertEqual(LocalModelCatalog.all.count, 1)\n        XCTAssertEqual(LocalModelCatalog.presentationOrder.count, 1)\n        XCTAssertEqual(LocalModelCatalog.all.first?.id, target.id)\n        XCTAssertFalse(target.isIPhone12SafeDefault)\n        XCTAssertEqual(target.deviceFit, .extreme)\n        XCTAssertTrue(target.parameterLabel.localizedCaseInsensitiveContains("27B"))\n        XCTAssertTrue(\n            [target.id, target.displayName, target.details]\n                .joined(separator: " ")\n                .localizedCaseInsensitiveContains("3.8")\n        )\n\n        let forbiddenStaticClaims = [\n            "Device proven",\n            "physical-device canary proven",\n            "The proven iPhone 12 default",\n            "Qwen 3.6",\n            "Qwen3.6",\n            "Qwen 3.5",\n            "Qwen3.5",\n        ]\n        let staticPresentation = [\n            target.deviceFit.title,\n            target.benchmarkSummary,\n            target.details,\n        ].joined(separator: " ")\n        for claim in forbiddenStaticClaims {\n            XCTAssertFalse(\n                staticPresentation.localizedCaseInsensitiveContains(claim),\n                "Qwen 3.8 product metadata must not contain forbidden claim: \\(claim)"\n            )\n        }\n    }\n'''
if old_static_test in transport_tests:
    transport_tests = transport_tests.replace(old_static_test, new_static_test, 1)
elif new_static_test not in transport_tests:
    raise SystemExit("static catalog test block drifted")
transport_test_path.write_text(transport_tests, encoding="utf-8")

lifecycle_path = Path("AgentPadTests/AgentRuntimeLifecycleTests.swift")
lifecycle = lifecycle_path.read_text(encoding="utf-8")
old_lifecycle = '''    func testLocalCatalogPresentsNewestModelFirstButKeepsDeviceProvenDefault() throws {\n        let atlas = try XCTUnwrap(\n            LocalModelCatalog.variant(\n                for: "Siddh07ETH/Atlas-Coder-2-0.5B-Q4_K_M"\n            )\n        )\n\n        XCTAssertEqual(LocalModelCatalog.presentationOrder.first?.id, atlas.id)\n        XCTAssertEqual(atlas.releaseDateISO8601, "2026-07-20")\n        XCTAssertEqual(atlas.expectedBytes, 397_808_608)\n        XCTAssertEqual(\n            atlas.expectedSHA256,\n            "3df10fa96ad19ddcda435506781308c9eeeedaab35f1a0a86ff198ad0e1ce871"\n        )\n        XCTAssertEqual(atlas.deviceFit, .ultraLight)\n        XCTAssertTrue(LocalModelCatalog.defaultVariant.isIPhone12SafeDefault)\n        XCTAssertEqual(LocalModelCatalog.defaultVariant.deviceFit, .deviceProven)\n    }\n\n    func testRuntimeMemoryAdmissionFailsClosedBeforeFirstAllocation() throws {\n        let atlas = try XCTUnwrap(\n            LocalModelCatalog.variant(\n                for: "Siddh07ETH/Atlas-Coder-2-0.5B-Q4_K_M"\n            )\n        )\n\n        XCTAssertNil(\n            LocalModelRuntimeMemoryPolicy.admissionMessage(\n                for: atlas,\n                availableMemory: atlas.minimumAvailableMemoryBeforeLoadBytes,\n                thermalState: .nominal\n            )\n        )\n        let blocked = LocalModelRuntimeMemoryPolicy.admissionMessage(\n            for: atlas,\n            availableMemory: atlas.minimumAvailableMemoryBeforeLoadBytes - 1,\n            thermalState: .nominal\n        )\n        XCTAssertNotNil(blocked)\n        XCTAssertTrue(blocked?.contains("before first-prompt allocation") == true)\n    }\n\n    func testRuntimeMemoryAdmissionBlocksHotLargeModelButAllowsUltraLight() throws {\n        let qwen = LocalModelCatalog.defaultVariant\n        let atlas = try XCTUnwrap(\n            LocalModelCatalog.variant(\n                for: "Siddh07ETH/Atlas-Coder-2-0.5B-Q4_K_M"\n            )\n        )\n\n        XCTAssertNotNil(\n            LocalModelRuntimeMemoryPolicy.admissionMessage(\n                for: qwen,\n                availableMemory: nil,\n                thermalState: .serious\n            )\n        )\n        XCTAssertNil(\n            LocalModelRuntimeMemoryPolicy.admissionMessage(\n                for: atlas,\n                availableMemory: nil,\n                thermalState: .serious\n            )\n        )\n        XCTAssertNotNil(\n            LocalModelRuntimeMemoryPolicy.admissionMessage(\n                for: atlas,\n                availableMemory: nil,\n                thermalState: .critical\n            )\n        )\n    }\n'''
new_lifecycle = '''    func testLocalCatalogPresentsOnlyQwen38TargetAndNeverFallsBack() throws {\n        let target = LocalModelCatalog.defaultVariant\n        XCTAssertEqual(LocalModelCatalog.presentationOrder.count, 1)\n        XCTAssertEqual(LocalModelCatalog.all.count, 1)\n        XCTAssertEqual(LocalModelCatalog.presentationOrder.first?.id, target.id)\n        XCTAssertEqual(LocalModelCatalog.safestVariant(forPhysicalMemory: 1).id, target.id)\n        XCTAssertNil(LocalModelCatalog.variant(for: "Siddh07ETH/Atlas-Coder-2-0.5B-Q4_K_M"))\n        XCTAssertNil(LocalModelCatalog.variant(for: "Qwen/Qwen2.5-Coder-1.5B-Instruct-Q4_K_M"))\n        XCTAssertEqual(target.deviceFit, .extreme)\n    }\n\n    func testRuntimeMemoryAdmissionFailsClosedBeforeFirstAllocation() throws {\n        var target = LocalModelCatalog.defaultVariant\n        // The unreleased sentinel intentionally has no load budget yet. Exercise\n        // the admission boundary with an explicit Qwen-3.8-shaped test variant.\n        target = LocalModelVariant(\n            id: "qwen38:test-memory",\n            displayName: "Qwen 3.8 27B Test",\n            shortName: "Qwen 3.8 27B",\n            quantization: "TEST",\n            filename: "qwen38-test.gguf",\n            downloadURL: URL(string: "https://example.com/qwen38-test.gguf")!,\n            expectedBytes: 1,\n            expectedSHA256: String(repeating: "a", count: 64),\n            minimumPhysicalMemoryBytes: 1,\n            recommendedFreeDiskBytes: 1,\n            contextTokens: 4_096,\n            batchTokens: 8,\n            maxNewTokens: 64,\n            maxGenerationSeconds: 30,\n            useGPU: false,\n            gpuLayerCount: 0,\n            generationThreadCount: 2,\n            batchThreadCount: 2,\n            isIPhone12SafeDefault: false,\n            releaseDateISO8601: "2026-08-17",\n            releaseDateLabel: "Test",\n            parameterLabel: "27B",\n            licenseLabel: "test",\n            benchmarkSummary: "Unit test",\n            capabilitySummary: "Unit test",\n            deviceFit: .extreme,\n            estimatedPeakMemoryBytes: 1_500_000_000,\n            minimumAvailableMemoryBeforeLoadBytes: 1_200_000_000,\n            sourceURL: URL(string: "https://example.com/qwen38-test")!,\n            details: "Qwen 3.8 memory-boundary test fixture."\n        )\n\n        XCTAssertNil(\n            LocalModelRuntimeMemoryPolicy.admissionMessage(\n                for: target,\n                availableMemory: target.minimumAvailableMemoryBeforeLoadBytes,\n                thermalState: .nominal\n            )\n        )\n        let blocked = LocalModelRuntimeMemoryPolicy.admissionMessage(\n            for: target,\n            availableMemory: target.minimumAvailableMemoryBeforeLoadBytes - 1,\n            thermalState: .nominal\n        )\n        XCTAssertNotNil(blocked)\n        XCTAssertTrue(blocked?.contains("before first-prompt allocation") == true)\n    }\n\n    func testRuntimeMemoryAdmissionBlocksQwen38WhenThermallySerious() {\n        let target = LocalModelCatalog.defaultVariant\n        XCTAssertNotNil(\n            LocalModelRuntimeMemoryPolicy.admissionMessage(\n                for: target,\n                availableMemory: nil,\n                thermalState: .serious\n            )\n        )\n        XCTAssertNotNil(\n            LocalModelRuntimeMemoryPolicy.admissionMessage(\n                for: target,\n                availableMemory: nil,\n                thermalState: .critical\n            )\n        )\n    }\n'''
if old_lifecycle in lifecycle:
    lifecycle = lifecycle.replace(old_lifecycle, new_lifecycle, 1)
elif new_lifecycle not in lifecycle:
    raise SystemExit("lifecycle catalog test block drifted")
lifecycle_path.write_text(lifecycle, encoding="utf-8")

print("Qwen 3.8 catalog authority + stale test contract patched")
